// Service function to create automatic tasks
const createAutomaticTask = async (operationData, currentUser, notes = '') => {
  try {
    const taskData = {
      title: `Post-Processing: ${MACHINE_OPERATIONS[operationData.operation]?.name || operationData.operation}`,
      description: `Automatic task generated for completed PO operation. PO: ${operationData.poNumber}, Item: ${operationData.itemDescription}. ${notes ? `Notes: ${notes}` : ''}`,
      // priority: 'medium',
      category: 'quality',
      department: 'quality-control',
      dueDate: new Date(Date.now() + 24 * 60 * 60 * 1000), // 24 hours from now
      estimatedTime: 60, // 1 hour default
      status: 'pending',
      completed: false,
      progress: 0,
      sequence: [
        { step: 'Quality inspection of machined part', completed: false },
        { step: 'Documentation and certification', completed: false },
        { step: 'Prepare for next production stage', completed: false }
      ],
      sourcePO: operationData.poId,
      sourcePONumber: operationData.poNumber,
      sourceOperation: operationData.operation,
      sourceItemIndex: operationData.itemIndex,
      sourceItemDescription: operationData.itemDescription,
      sourceVendor: operationData.vendorId,
      sourceVendorName: operationData.vendorName,
      sourceQuantity: operationData.quantity,
      sourceUnit: operationData.unit,
      sourceSpecifications: operationData.specifications,
      sourceMaterial: operationData.material,
      autoGenerated: true,
      createdAt: serverTimestamp(),
      updatedAt: serverTimestamp(),
      createdBy: {
        uid: currentUser?.uid || 'system',
        name: currentUser?.displayName || 'System Auto-Generator',
        email: currentUser?.email || 'system@company.com'
      }
    };

    // Check if task already exists for this operation
    const existingTaskQuery = query(
      collection(db, 'industrialTasks'),
      where('sourcePO', '==', operationData.poId),
      where('sourceOperation', '==', operationData.operation),
      where('sourceItemIndex', '==', operationData.itemIndex)
    );
    
    const existingTasks = await getDocs(existingTaskQuery);
    
    if (existingTasks.empty) {
      await addDoc(collection(db, 'industrialTasks'), taskData);
      return true;
    }
    return false;
  } catch (error) {
    console.error('Error creating automatic task:', error);
    throw error;
  }
};

// Enhanced Custom Hook for Real-time PO Monitoring with Connection Management
const usePOStatusManager = () => {
  const [pos, setPOs] = useState([]);
  const [vendors, setVendors] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [connectionStatus, setConnectionStatus] = useState('connected');
  const { showSuccess, showError } = useNotification();
  const unsubscribeRef = useRef(null);

  const fetchData = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const [poList, vendorList] = await Promise.all([
        getAllPOsWithOperations(),
        getAllVendors(),
      ]);
      
      // Process POs to extract operations with enhanced normalization
      const processedPOs = (poList || []).map(po => {
        const operations = [];
        const operationsStatus = {};
        const operationsMeta = {};
        
        // Extract operations from items with robust data handling
        if (po.items && Array.isArray(po.items)) {
          po.items.forEach((item, itemIndex) => {
            if (item.operation) {
              const operationKey = `${itemIndex}_${item.operation}`;
              const operationData = {
                operation: item.operation,
                itemIndex,
                itemDescription: item.description || `Item ${itemIndex + 1}`,
                quantity: item.quantity || 0,
                unit: item.unit || 'pcs',
                unitPrice: item.unitPrice || 0,
                specifications: item.specifications || '',
                deliveryDate: item.deliveryDate || po.deliveryDate,
                material: item.material || '',
                tolerances: item.tolerances || '',
                estimatedHours: item.estimatedHours || 0
              };
              
              operations.push(operationData);
              
              // Enhanced status normalization for both flat and nested structures
              let currentStatus = 'pending';
              if (po.operationsStatus) {
                if (typeof po.operationsStatus[operationKey] === 'string') {
                  currentStatus = po.operationsStatus[operationKey];
                } else if (po.operationsStatus[itemIndex]?.[item.operation]) {
                  currentStatus = po.operationsStatus[itemIndex][item.operation];
                }
              }
              
              operationsStatus[operationKey] = currentStatus;
              
              // Enhanced meta normalization
              const existingMeta = po.operationsMeta?.[operationKey] || {};
              operationsMeta[operationKey] = {
                createdAt: existingMeta.createdAt || po.createdAt || serverTimestamp(),
                updatedAt: existingMeta.updatedAt || po.updatedAt || po.createdAt || serverTimestamp(),
                updatedBy: existingMeta.updatedBy || { name: 'System', role: 'system' },
                ...existingMeta
              };
            }
          });
        }
        
        return {
          ...po,
          operations,
          operationsStatus,
          operationsMeta,
          totalOperations: operations.length,
          completedOperations: Object.values(operationsStatus).filter(status => status === 'completed').length
        };
      });
      
      setPOs(processedPOs);
      setVendors(vendorList || []);
      setConnectionStatus('connected');
    } catch (err) {
      console.error('Failed to fetch data:', err);
      setError(err.message);
      setConnectionStatus('error');
      showError('Failed to load operations data');
    } finally {
      setLoading(false);
    }
  }, [showError]);

  // Enhanced Real-time listener with connection management
  useEffect(() => {
    const setupRealtimeListener = () => {
      try {
        if (unsubscribeRef.current) {
          unsubscribeRef.current();
        }

        const poQuery = query(
          collection(db, 'purchaseOrders'), 
          orderBy('createdAt', 'desc')
        );

        unsubscribeRef.current = onSnapshot(
          poQuery,
          (snapshot) => {
            setConnectionStatus('connected');
            
            // Process all changes for immediate UI updates
            const hasRelevantChanges = snapshot.docChanges().some(change => {
              if (change.type === 'added' || change.type === 'modified') {
                const poData = change.doc.data();
                return poData.operationsStatus || poData.operationsMeta;
              }
              return true;
            });

            if (hasRelevantChanges) {
              fetchData(); // Refresh data to include all changes
            }
          },
          (error) => {
            console.error('Real-time PO listener error:', error);
            setConnectionStatus('error');
            showError('Real-time updates disconnected');
          }
        );
      } catch (error) {
        console.error('Error setting up real-time listener:', error);
        setConnectionStatus('error');
      }
    };

    setupRealtimeListener();

    return () => {
      if (unsubscribeRef.current) {
        unsubscribeRef.current();
      }
    };
  }, [fetchData, showError]);

  // Initial data fetch
  useEffect(() => {
    fetchData();
  }, [fetchData]);

  const retryConnection = () => {
    setConnectionStatus('connecting');
    fetchData();
  };

  return { 
    pos, 
    vendors, 
    loading, 
    error, 
    connectionStatus,
    refetch: fetchData,
    retryConnection 
  };
};

