// Enhanced Service Function with Retry Logic
const updatePOOperationStatusWithRetry = async (poId, operation, itemIndex, newStatus, currentUser, notes = '', retries = 3) => {
  for (let attempt = 1; attempt <= retries; attempt++) {
    try {
      const result = await updatePOOperationStatusSvc(poId, operation, itemIndex, newStatus, currentUser, notes);
      return result;
    } catch (error) {
      if (attempt === retries) {
        throw error;
      }
      // Wait before retrying (exponential backoff)
      await new Promise(resolve => setTimeout(resolve, 1000 * attempt));
    }
  }
};

